-- 218_t_partner_metric2_revoke_anon_REHEARSAL.sql
--
-- GENERATED by supabase/recon/t-partner-metric2-build-rehearsal.LOCAL.py from
-- supabase/recon/218_REHEARSAL.template.sql. Edit the template, then rebuild;
-- the migration body and its guard are spliced in, never retyped.
--
-- Rehearsal for supabase/migrations/218_t_partner_metric2_revoke_anon.sql. Run
-- in the Supabase SQL editor. Everything through the ROLLBACK is inside
-- BEGIN ... ROLLBACK; production is not modified. ONE result set.
--
-- Part A  anon's privilege measured BEFORE the body (E1's premise), then the
--         migration body INCLUDING ITS DO GUARD, spliced verbatim; the catalog
--         and one throwaway partner.
-- Part B  B1 and B2 are POSITIVE: a signed-in user and the service role still
--         count. B3 is the point: anon is refused.
-- Part D  218's own guard, unmutated (D0) and against two mutations, each
--         asserting the mutation LANDED first.
-- Part E  the premise: before 218, anon could call it.
-- Part F  baseline and identity.
-- Part G  nothing escaped -- OUTSIDE THE TRANSACTION.
--
-- THROWAWAY ONLY: one CLONE of a featured_partners row with a new id, a
-- reh218- slug, user_id NULL, status 'active' and zeroed counters.

BEGIN;

-- E1's premise, read before anything in this file changes a privilege.
CREATE TEMP TABLE reh_pre AS
SELECT has_function_privilege('anon', to_regprocedure('public.increment_partner_metric(uuid, text)'), 'EXECUTE')
       AS anon_before;

-- ══════════════════════════════════════════════════════════════════════════
-- PART A: the migration body, spliced verbatim from
--         supabase/migrations/218_t_partner_metric2_revoke_anon.sql
--         (its BEGIN/COMMIT and its migrations_applied INSERT omitted)
-- ══════════════════════════════════════════════════════════════════════════

-- @@MIGRATION_BODY@@

-- ══════════════════════════════════════════════════════════════════════════
-- PARTS B to F
-- ══════════════════════════════════════════════════════════════════════════
CREATE TEMP TABLE reh_probe (seq integer, check_name text, detail text, passed boolean);

DO $outer$
DECLARE
  v_guard text := $guard$@@GUARD_DO_BLOCK@@$guard$;

  k_active uuid := gen_random_uuid();
  k_fn oid := to_regprocedure('public.increment_partner_metric(uuid, text)');
  v_n integer; v_imp integer; v_clk integer;

  a1_state text := '(never ran)'; a1_ok boolean := false;
  a2_state text := '(never ran)'; a2_ok boolean := false;
  b1_state text := '(never ran)'; b1_ok boolean := false;
  b2_state text := '(never ran)'; b2_ok boolean := false;
  b3_state text := '(never ran)'; b3_ok boolean := false;
  d0_state text := '(never ran)'; d0_ok boolean := false;
  d1_state text := '(never ran)'; d1_ok boolean := false;
  d2_state text := '(never ran)'; d2_ok boolean := false;
  e1_state text := '(never ran)'; e1_ok boolean := false;
  f1_state text := '(never ran)'; f1_ok boolean := false;
  f2_state text := '(never ran)'; f2_ok boolean := false;
BEGIN

-- A1: the catalog, independently of the guard.
a1_state := 'anon=' || has_function_privilege('anon', k_fn, 'EXECUTE')
  || '; authenticated=' || has_function_privilege('authenticated', k_fn, 'EXECUTE')
  || '; service_role=' || has_function_privilege('service_role', k_fn, 'EXECUTE')
  || '; PUBLIC=' || EXISTS (SELECT 1 FROM pg_proc p, aclexplode(p.proacl) a WHERE p.oid = k_fn AND a.grantee = 0);
a1_ok := a1_state = 'anon=false; authenticated=true; service_role=true; PUBLIC=false';

-- A2: scaffolding. One active clone, counters zeroed.
BEGIN
  INSERT INTO public.featured_partners
  SELECT r.*
    FROM public.featured_partners fp
    CROSS JOIN LATERAL jsonb_populate_record(
      NULL::public.featured_partners,
      to_jsonb(fp.*) || jsonb_build_object(
        'id', k_active, 'slug', 'reh218-active', 'user_id', NULL, 'status', 'active',
        'business_name', 'REHEARSAL THROWAWAY (roll back)',
        'total_impressions', 0, 'total_clicks', 0, 'total_bookings', 0)
    ) AS r
   ORDER BY fp.created_at NULLS LAST
   LIMIT 1;
  SELECT count(*) INTO v_n FROM public.featured_partners WHERE id = k_active;
  a2_state := v_n || ' of 1 throwaway partner created';
  a2_ok := v_n = 1;
EXCEPTION WHEN OTHERS THEN
  a2_state := 'scaffolding failed: ' || SQLSTATE || ' ' || SQLERRM;
END;

-- ── PART B ────────────────────────────────────────────────────────────────

-- B1: POSITIVE. The banner's real caller, a signed-in user, still counts.
BEGIN
  PERFORM set_config('request.jwt.claims',
    json_build_object('sub', gen_random_uuid()::text, 'role', 'authenticated')::text, true);
  SET LOCAL ROLE authenticated;
  BEGIN
    PERFORM public.increment_partner_metric(k_active, 'total_impressions');
  EXCEPTION WHEN OTHERS THEN
    b1_state := 'REFUSED a signed-in impression: ' || SQLSTATE || ' ' || SQLERRM;
  END;
  RESET ROLE; PERFORM set_config('request.jwt.claims', NULL, true);
  SELECT total_impressions, total_clicks INTO v_imp, v_clk FROM public.featured_partners WHERE id = k_active;
  IF b1_state = '(never ran)' THEN
    b1_state := 'impressions ' || v_imp || ', clicks ' || v_clk;
    b1_ok := v_imp = 1 AND v_clk = 0;
  END IF;
EXCEPTION WHEN OTHERS THEN
  RESET ROLE; b1_state := 'scaffolding failed: ' || SQLERRM; b1_ok := false;
END;

-- B2: POSITIVE. The service role still counts.
BEGIN
  SET LOCAL ROLE service_role;
  BEGIN
    PERFORM public.increment_partner_metric(k_active, 'total_clicks');
  EXCEPTION WHEN OTHERS THEN
    b2_state := 'REFUSED the service role: ' || SQLSTATE || ' ' || SQLERRM;
  END;
  RESET ROLE;
  SELECT total_impressions, total_clicks INTO v_imp, v_clk FROM public.featured_partners WHERE id = k_active;
  IF b2_state = '(never ran)' THEN
    b2_state := 'impressions ' || v_imp || ', clicks ' || v_clk;
    b2_ok := v_imp = 1 AND v_clk = 1;
  END IF;
EXCEPTION WHEN OTHERS THEN
  RESET ROLE; b2_state := 'scaffolding failed: ' || SQLERRM; b2_ok := false;
END;

-- B3: anon is refused 42501, and nothing moved.
BEGIN
  PERFORM set_config('request.jwt.claims', NULL, true);
  SET LOCAL ROLE anon;
  BEGIN
    PERFORM public.increment_partner_metric(k_active, 'total_impressions');
    b3_state := 'ACCEPTED an anon call';
  EXCEPTION WHEN OTHERS THEN
    b3_state := SQLSTATE || ' ' || SQLERRM;
  END;
  RESET ROLE;
  SELECT total_impressions, total_clicks INTO v_imp, v_clk FROM public.featured_partners WHERE id = k_active;
  b3_state := b3_state || '; counters still ' || v_imp || '/' || v_clk;
  b3_ok := b3_state LIKE '42501 %increment_partner_metric%' AND v_imp = 1 AND v_clk = 1;
EXCEPTION WHEN OTHERS THEN
  RESET ROLE; b3_state := 'scaffolding failed: ' || SQLERRM; b3_ok := false;
END;

-- ── PART D: 218's guard ───────────────────────────────────────────────────

-- D0: POSITIVE. The guard passes on the real end state.
BEGIN
  EXECUTE v_guard;
  d0_state := 'guard passed'; d0_ok := true;
EXCEPTION WHEN OTHERS THEN
  d0_state := 'guard FAILED on the real end state: ' || SQLERRM;
END;

-- D1: anon given EXECUTE back.
BEGIN
  GRANT EXECUTE ON FUNCTION public.increment_partner_metric(uuid, text) TO anon;
  IF NOT has_function_privilege('anon', k_fn, 'EXECUTE') THEN
    d1_state := 'mutation did not land'; RAISE EXCEPTION 'D1_ROLLBACK';
  END IF;
  BEGIN
    EXECUTE v_guard;
    d1_state := 'guard PASSED with anon able to execute';
  EXCEPTION WHEN OTHERS THEN
    d1_state := 'fired: ' || SQLERRM; d1_ok := SQLERRM LIKE '218 ABORTED%anon%';
  END;
  RAISE EXCEPTION 'D1_ROLLBACK';
EXCEPTION WHEN OTHERS THEN
  IF SQLERRM <> 'D1_ROLLBACK' THEN d1_state := 'scaffolding failed: ' || SQLERRM; d1_ok := false; END IF;
END;

-- D2: authenticated loses EXECUTE (the over-correction this must not allow).
BEGIN
  REVOKE EXECUTE ON FUNCTION public.increment_partner_metric(uuid, text) FROM authenticated;
  IF has_function_privilege('authenticated', k_fn, 'EXECUTE') THEN
    d2_state := 'mutation did not land'; RAISE EXCEPTION 'D2_ROLLBACK';
  END IF;
  BEGIN
    EXECUTE v_guard;
    d2_state := 'guard PASSED with authenticated unable to execute';
  EXCEPTION WHEN OTHERS THEN
    d2_state := 'fired: ' || SQLERRM; d2_ok := SQLERRM LIKE '218 ABORTED%authenticated%';
  END;
  RAISE EXCEPTION 'D2_ROLLBACK';
EXCEPTION WHEN OTHERS THEN
  IF SQLERRM <> 'D2_ROLLBACK' THEN d2_state := 'scaffolding failed: ' || SQLERRM; d2_ok := false; END IF;
END;

-- ── PART E: the premise ───────────────────────────────────────────────────

-- E1: before this file touched anything, anon COULD call it (217's grant).
SELECT anon_before INTO STRICT e1_ok FROM reh_pre;
e1_state := 'anon could execute before 218: ' || coalesce(e1_ok::text, 'NULL (function missing?)');
e1_ok := coalesce(e1_ok, false);

-- ── PART F: baseline and identity ─────────────────────────────────────────

-- F1: the precondition. 217 is applied and recorded.
f1_state := '217 recorded: '
  || EXISTS (SELECT 1 FROM public.migrations_applied WHERE migration = '217_t_partner_metric1_increment_partner_metric');
f1_ok := f1_state = '217 recorded: true';

-- F2: the arms came back to the editor's role.
f2_state := 'current_user ' || current_user || ', auth.uid() ' || coalesce((SELECT auth.uid())::text, 'NULL');
f2_ok := current_user NOT IN ('anon', 'authenticated', 'service_role') AND (SELECT auth.uid()) IS NULL;

INSERT INTO reh_probe VALUES
  (1,  'A1 catalog: anon no, authenticated yes, service_role yes, PUBLIC no', a1_state, a1_ok),
  (2,  'A2 scaffolding: one active throwaway partner', a2_state, a2_ok),
  (3,  'B1 POSITIVE: a signed-in user still adds exactly one impression', b1_state, b1_ok),
  (4,  'B2 POSITIVE: the service role still adds exactly one click', b2_state, b2_ok),
  (5,  'B3 anon is refused 42501 and nothing moves', b3_state, b3_ok),
  (6,  'D0 POSITIVE: 218''s guard passes on the real end state', d0_state, d0_ok),
  (7,  'D1 guard fires when anon can execute again', d1_state, d1_ok),
  (8,  'D2 guard fires when authenticated loses execute', d2_state, d2_ok),
  (9,  'E1 PREMISE: before 218, anon could call it', e1_state, e1_ok),
  (10, 'F1 BASELINE: 217 is applied and recorded', f1_state, f1_ok),
  (11, 'F2 IDENTITY: back to the editor''s role, auth.uid() NULL', f2_state, f2_ok);

END $outer$;

-- The one result set for the transaction. Every row must read PASS. 11 of 11.
SELECT seq, CASE WHEN coalesce(passed, false) THEN 'PASS' ELSE 'FAIL' END AS result, check_name,
       coalesce(detail, '(probe row missing)') AS detail
FROM reh_probe ORDER BY seq;

ROLLBACK;

-- ══════════════════════════════════════════════════════════════════════════
-- PART G: nothing escaped. RUN AS ITS OWN STATEMENT, AFTER THE ROLLBACK.
-- Expected BEFORE apply: anon still has EXECUTE, no throwaway, 218 not recorded.
-- ══════════════════════════════════════════════════════════════════════════

SELECT t.seq, CASE WHEN t.passed THEN 'PASS' ELSE 'FAIL' END AS result, t.check_name, t.detail
FROM (VALUES
  (1, 'G1 anon still has EXECUTE (the revoke rolled back)',
      'anon=' || has_function_privilege('anon', to_regprocedure('public.increment_partner_metric(uuid, text)'), 'EXECUTE'),
      has_function_privilege('anon', to_regprocedure('public.increment_partner_metric(uuid, text)'), 'EXECUTE')),
  (2, 'G2 no throwaway partner escaped',
      (SELECT count(*) FROM public.featured_partners WHERE slug LIKE 'reh218-%')::text || ' partners',
      (SELECT count(*) FROM public.featured_partners WHERE slug LIKE 'reh218-%') = 0),
  (3, 'G3 218 is NOT recorded as applied',
      (SELECT coalesce(string_agg(migration, ', '), '(not recorded, as expected)')
         FROM public.migrations_applied WHERE migration LIKE '218%'),
      (SELECT count(*) FROM public.migrations_applied WHERE migration LIKE '218%') = 0)
) AS t(seq, check_name, detail, passed)
ORDER BY t.seq;
